import os, glob, re, json

def load():
    d = os.environ.get('RLM_SESSION_DIR', '')
    # Try to find the jsonl file
    t = os.path.join(d, os.path.basename(d) + '.jsonl')
    try:
        G = {}
        with open(t) as f:
            content = f.read()
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in content[m.end():].split('\n')[:h]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        return G
    except Exception as e:
        print(f"Load error: {e}")
        return G

G = load()
print("Loaded keys:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k} shape: {len(v)}x{len(v[0]) if v else 0}")

